module.exports = class DemoHello {
  constructor(context) {
    this.id = context.id;
    this.host = context.host;
  }
  async onload() {
    this.host.log.info('demo plugin onload');
    const version = await this.host.getVersion();
    this.host.log.info('host app version: ' + version);
    await this.host.storage.set('lastLoad', String(Date.now()));
    const lastLoad = await this.host.storage.get('lastLoad');
    this.host.log.info('storage roundtrip: ' + lastLoad);
    this.host.registerBookSourceEngine({
      search: async (source, keyword) => {
        this.host.log.info('search called: ' + keyword);
        return [
          {
            title: 'Demo book: ' + keyword,
            author: 'demo',
            detailUrl: source.bookSourceUrl || 'https://example.com',
          },
        ];
      },
      getChapterList: async () => [{ title: 'Chapter 1', url: 'https://example.com/1' }],
      getChapterContent: async (source, chapter) =>
        'Hello from the demo plugin: ' + chapter.title,
    });
  }
  async onunload() {
    this.host.log.info('demo plugin onunload');
  }
};
